CREATE FUNCTION map_in_malaga_v1(lat double precision, lon double precision) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE SET search_path FROM CURRENT AS $$
BEGIN
  RETURN map_xy_v1(lat, lon) <@ map_outline_v1();
END $$;

-- Only the 100 m cell determines this public point, never the viewport or zoom.
-- If its centre is offshore/across a border, project that CENTRE onto the closest
-- official boundary segment. This does not use the original point for clamping.
CREATE FUNCTION map_public_point_v1(lat double precision, lon double precision) RETURNS point
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE SET search_path FROM CURRENT AS $$
DECLARE
  p point := map_xy_v1(lat, lon);
  snapped point := point((floor(p[0] / 100) + 0.5) * 100, (floor(p[1] / 100) + 0.5) * 100);
  vertices point[];
  candidate point;
  closest point;
  distance double precision := 'Infinity'::double precision;
  d double precision;
BEGIN
  IF snapped <@ map_outline_v1() THEN RETURN snapped; END IF;
  vertices := map_vertices_v1();
  FOR n IN 1 .. array_length(vertices, 1) - 1 LOOP
    candidate := snapped ## lseg(vertices[n], vertices[n + 1]);
    d := snapped <-> candidate;
    IF d < distance THEN closest := candidate; distance := d; END IF;
  END LOOP;
  RETURN closest;
END $$;

CREATE INDEX maps_exact_location_idx ON incidents USING gist (map_xy_v1(latitude, longitude))
  WHERE map_in_malaga_v1(latitude, longitude);
CREATE INDEX maps_public_location_idx ON incidents USING gist (map_public_point_v1(latitude, longitude))
  WHERE map_in_malaga_v1(latitude, longitude);
CREATE INDEX maps_validated_review_idx ON incident_reviews (incident_id) WHERE decision = 'VALIDATE';
